// <auto-generated />
namespace LiveScore.WebApi.Shared.Middlewares
{
    using Microsoft.AspNetCore.Builder;
    using Microsoft.Extensions.DependencyInjection;
    using Swashbuckle.AspNetCore.Swagger;

    public static class SwaggerMiddleware
    {
        public static void AddSwagger(this IServiceCollection services)
        {
            services.AddSwaggerGen(c =>
            {
                c.SwaggerDoc("v1", new Info { Title = "Live Scores API", Version = "v1" });
            });
        }

        public static void ConfigureSwagger(this IApplicationBuilder application)
        {
            application.UseSwagger().UseSwaggerUI(c =>
             {
                 c.SwaggerEndpoint($"../swagger/v1/swagger.json", "Score247 API Docs");
             })
                .UseMvc(routes =>
                {
                    routes.MapRoute(
                        name: "default",
                        template: "{controller=Home}/{action=Index}");
                });
        }
    }
}